def group_list(lst, group_size):
    result = []
    for i in range(0, len(lst), group_size):
        result.append(lst[i:i + group_size])
    return result

def factorial(n):
    result = 1
    for number in range(1, n + 1):
        result *= number
    return result

def unique_items(items):
    result = []
    for item in items:
        if item not in result:
            result.append(item)
    return result
